package main

const pageHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>YourMove Realize</title><link rel="icon" type="image/svg+xml" href="/identity/app-icon.svg"><meta name="theme-color" content="#F5F4F1" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#191C22" media="(prefers-color-scheme: dark)"><meta property="og:title" content="YourMove Realize"><meta property="og:image" content="/identity/app-icon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;600;700;800&display=swap" rel="stylesheet"><script>try{document.documentElement.dataset.theme=localStorage.getItem('theme')||''}catch(e){}</script><style>
:root{color-scheme:light;--bg:#F5F4F1;--surface:#FFFFFF;--ink:#242933;--muted:#5F6672;--line:#D9DDE3;--blue:#3459A5;--green:#0FB56D;--green-deep:#0F6E44;--mark-green:#215C43;--wash:#ECEEF1;--glow:rgba(15,181,109,.10);--paper:#FBFAF7;--clay:#E8E0D2;--on:#fff;--panel:#1F2630;--panel-ink:#F2F5F8;--panel-mute:#B9C2CD}
[data-theme=dark]{color-scheme:dark;--bg:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#B8C0CC;--line:#424955;--blue:#AAC5FF;--green:#3ED598;--green-deep:#78B696;--mark-green:#78B696;--wash:#2B3039;--glow:rgba(62,213,152,.14);--paper:#1E2229;--clay:#2E333C;--on:#191C22}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]){color-scheme:dark;--bg:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#B8C0CC;--line:#424955;--blue:#AAC5FF;--green:#3ED598;--green-deep:#78B696;--mark-green:#78B696;--wash:#2B3039;--glow:rgba(62,213,152,.14);--paper:#1E2229;--clay:#2E333C;--on:#191C22}}
*{box-sizing:border-box}
html,body{max-width:100%;overflow-x:clip}
html{min-height:100%}
body{margin:0;background:var(--bg);background-image:radial-gradient(1100px 480px at 85% -8%,var(--glow),transparent 70%),radial-gradient(900px 420px at -10% 12%,var(--glow),transparent 65%);color:var(--ink);font:17px/1.55 Jost,"Avenir Next",sans-serif;font-family:Jost,"Avenir Next",sans-serif;min-height:100dvh;display:flex;flex-direction:column}
main,.conversation,.conversation>section,.conversation .context,.question,.message,.composer,footer{max-width:100%}
.conversation>section,.conversation .context,.question,.message,.composer{min-width:0}
.question p,.message p,.signal blockquote,.context pre,.preview,blockquote,.quote,.lede{overflow-wrap:anywhere;word-break:break-word}
.context pre,.preview,blockquote,.quote,textarea,input{max-width:100%}
img,svg{max-width:100%;height:auto}
header{max-width:none;padding:16px clamp(22px,5vw,72px);display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(12px)}
.brand{display:flex;align-items:center;gap:18px}
.brand .lockup{width:min(264px,58vw);height:auto;display:flex;align-items:flex-end;gap:10px}
.brand .lockup .ym{height:34px;width:auto;flex:none}
.brand .lockup .realize{height:21px;width:auto;flex:none;overflow:visible;transform:translateY(-7px)}
.brand span.lockup{border:0;padding:0;margin:0}
main{flex:1;width:100%;max-width:1440px;margin:0 auto;padding:clamp(28px,4vw,56px) clamp(22px,6vw,90px) 96px}
h1,h2,h3,p{margin:0 0 18px}
h1{font:500 clamp(42px,5.6vw,72px)/1.02 Jost,sans-serif;letter-spacing:-.055em;text-wrap:balance}
h2{font:700 clamp(30px,3vw,46px)/1.15 Jost,sans-serif;letter-spacing:-.04em}
h3{font-size:19px;line-height:1.3}
.lede{font-size:clamp(19px,1.7vw,23px);line-height:1.55;color:var(--muted)}
.muted,small{color:var(--muted)}
small{font-size:13px}
.eyebrow{display:inline-block;background:var(--wash);border:1px solid var(--line);border-radius:999px;padding:6px 14px;font-size:12px;font-weight:700;letter-spacing:.14em}
button,.button{display:inline-block;background:var(--blue);color:var(--on);border:1px solid var(--blue);padding:13px 22px;border-radius:999px;font:inherit;font-weight:600;cursor:pointer;text-decoration:none;box-shadow:0 1px 2px rgba(15,25,20,.10),0 12px 28px -18px rgba(15,110,68,.45);transition:transform .18s,filter .18s}
button:hover,.button:hover{filter:brightness(.92);transform:translateY(-1px)}
button.secondary,.button.secondary{background:transparent;color:var(--ink);border-color:var(--line);box-shadow:none}
.link{background:none;border:0;color:var(--blue);padding:4px 0;text-decoration:underline;box-shadow:none}
.theme{background:transparent;color:var(--ink);border-color:var(--line);font-size:13px;padding:6px 12px;box-shadow:none}
:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
textarea,input[type=text],input:not([type]){display:block;width:100%;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:14px 16px;font:inherit;font-size:16px}
textarea:focus,input:focus{border-color:var(--blue)}
label{display:block;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:16px 0 8px}
.notice{background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--green);padding:16px 20px;border-radius:12px;margin:0 0 24px}
.preview{white-space:pre-wrap;max-height:340px;overflow:auto;background:var(--surface);border:1px solid var(--line);padding:22px;font:14px/1.65 ui-monospace,monospace;border-radius:12px}
.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:24px 0}
footer{padding:28px clamp(22px,6vw,90px);color:var(--muted);font-size:14px;border-top:1px solid var(--line);display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin-top:clamp(32px,5vh,64px)}
.foot-lockup{display:flex;align-items:flex-end;gap:8px;flex:none}
.foot-lockup img{width:auto;height:26px;display:block}
.foot-lockup .logo-dark{display:none}
.foot-lockup .realize{height:16px;width:auto;flex:none;overflow:visible;transform:translateY(-5px)}
[data-theme=dark] .foot-lockup .logo-light{display:none}
[data-theme=dark] .foot-lockup .logo-dark{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]) .foot-lockup .logo-light{display:none}:root:not([data-theme=light]) .foot-lockup .logo-dark{display:block}}
.foot-byline{color:var(--muted);font-size:13px;line-height:1.5;max-width:340px;border-left:1px solid var(--line);padding-left:18px}
.brand img.logo-dark{display:none}
[data-theme=dark] .logo-light{display:none}
[data-theme=dark] .brand .logo-dark{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]) .logo-light{display:none}:root:not([data-theme=light]) .brand .logo-dark{display:block}}
/* Shell: unified immersive viewport */
.shell{width:100%}
.shell.immersive{display:grid;grid-template-columns:minmax(300px,360px) minmax(0,1fr);gap:clamp(28px,4vw,72px);align-items:start;min-height:calc(100dvh - 220px)}
.portrait{position:sticky;top:88px;align-self:start;background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(22px,2.5vw,32px);box-shadow:0 18px 44px -30px rgba(15,35,25,.35);overflow:auto;max-height:calc(100dvh - 140px)}
.portrait h2{font-size:clamp(26px,2.2vw,34px);font-weight:500;line-height:1.12;margin:12px 0 10px}
.portrait-purpose{font-size:15px;line-height:1.6;color:var(--muted)}
.portrait-focus{font-size:13px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--green-deep);margin:18px 0 14px}
.portrait-fragments{display:grid;gap:12px;margin:0}
.fragment{background:var(--paper);border:1px solid var(--line);border-left:3px solid var(--green);border-radius:0 14px 14px 14px;padding:14px 16px}
.fragment:nth-child(2){transform:rotate(-.4deg)}
.fragment:nth-child(3){transform:rotate(.4deg)}
.fragment blockquote{margin:0;font-size:16px;line-height:1.55;overflow-wrap:anywhere}
.fragment figcaption{font-size:12px;color:var(--muted);margin-top:8px}
.portrait-empty{border:1px dashed var(--line);border-radius:14px;padding:16px;font-size:15px}
.portrait-kept{margin-top:20px;border-top:1px solid var(--line);padding-top:16px}
.portrait-kept h3{font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0 0 10px}
.portrait-kept ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.portrait-kept li{background:var(--glow);border-radius:12px;padding:10px 14px;font-size:14px}
.portrait-kept li span{display:block;font-size:12px;color:var(--muted)}
.portrait-pending{margin:16px 0 0;font-size:14px;border-left:3px solid var(--blue);padding-left:12px}
.portrait-count{display:flex;gap:8px;align-items:center;margin-top:18px;font-size:13px;color:var(--muted)}
.portrait-count strong{color:var(--ink)}
.stage{min-width:0;max-width:860px}
.stage-wide{max-width:1000px}
/* Conversation focus */
.conversation{display:grid;grid-template-columns:minmax(0,1fr);gap:24px}
.kicker{color:var(--muted);font-size:14px;margin:0 0 8px}
.history{border:0;margin:0 0 8px}
.history summary{font-size:14px;color:var(--muted);cursor:pointer}
.conversation-recap{max-width:780px;border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:32px}
.conversation-recap summary{color:var(--muted);font-size:15px}
.message{max-width:90%;padding:16px 0;margin:0;border-top:1px solid var(--line)}
.message small{display:block;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--blue);margin-bottom:6px}
.message p{margin:0;white-space:pre-wrap}
.message.user{background:var(--surface);padding:20px 24px;margin:12px 0 28px auto;border-left:3px solid var(--line);border-radius:0 14px 14px 14px;border-top:0}
.message.user small{color:var(--muted)}
.question-focus{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(28px,4vw,44px);box-shadow:0 18px 44px -30px rgba(15,35,25,.35);margin:18px 0 0}
.question{font-size:clamp(26px,2.6vw,36px);line-height:1.3;max-width:100%;padding-top:8px;overflow-wrap:anywhere}
.question small{color:var(--green-deep)}
.composer{position:sticky;bottom:0;z-index:2;background:var(--bg);padding:16px 0 max(20px,env(safe-area-inset-bottom));border-top:1px solid var(--line);margin-top:20px}
.composer textarea{min-height:64px;max-height:240px;resize:none;font-size:16px}
.composer .actions{margin:12px 0 0}
.signal,.insight{background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--blue);border-radius:14px;box-shadow:0 18px 44px -30px rgba(15,35,25,.35);padding:22px;margin:24px 0}
.signal blockquote{font-size:clamp(20px,2vw,24px);color:var(--ink);border:0;padding:0;margin:12px 0}
.signal h3{font-size:clamp(24px,2.4vw,32px);margin:8px 0}
.pending-message{color:var(--muted)}
.waiting{display:none;font-size:14px;color:var(--muted)}
form.busy .waiting{display:block}
form.busy{opacity:.92}
.client-error{padding:16px;border-left:3px solid #B55;background:var(--surface);border-radius:8px;margin:12px 0}
.voice-controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-top:18px}
.voice-choice{margin:0;display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:650;color:var(--muted)}
.voice-choice select{min-height:48px;min-width:150px;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:10px 36px 10px 12px;font:inherit;font-size:16px}
.voice-controls .speak-question{min-height:48px}
.playback-status{display:block;color:var(--muted);font-size:14px;margin-top:6px}
/* Discovery: recognizably distinct cinematic moment */
.discovery-stage{margin:0}
.discovery-stage.full-bleed{background:var(--panel);color:var(--panel-ink);border-radius:24px;padding:clamp(32px,5vw,64px);position:relative;overflow:hidden}
.discovery-stage.full-bleed:after{content:"";position:absolute;inset:auto -20% -30% auto;width:420px;height:420px;background:radial-gradient(closest-side,var(--glow),transparent 70%);pointer-events:none}
.discovery-stage.full-bleed .lede{color:inherit;opacity:.86}
.discovery-stage.full-bleed .eyebrow{background:transparent;color:inherit;border-color:currentColor}
.discovery-stage>h1{font-size:clamp(44px,6vw,80px);max-width:900px;font-weight:500;line-height:1.02;letter-spacing:-.055em}
.discovery-stage>.lede{max-width:700px;margin-bottom:40px}
.discovery-map{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(32px,5vw,72px);align-items:start}
.source-anchor{margin:0;position:static;border-top:4px solid var(--green);padding-top:28px}
.source-anchor blockquote{border:0;padding:0;margin:24px 0;font-size:clamp(25px,2.6vw,36px);line-height:1.3;letter-spacing:-.025em;overflow-wrap:anywhere}
.source-anchor figcaption{font-size:13px;color:var(--muted);margin:20px 0 16px}
.discovery-stage.full-bleed .source-anchor figcaption{color:inherit;opacity:.7}
.discovery{background:transparent;border:0;border-top:1px solid currentColor;padding:28px 0;max-width:680px}
.discovery h2{font-weight:500;font-size:clamp(32px,3.8vw,48px);line-height:1.12}
.discovery h3{font-size:20px;margin:28px 0 10px}
.discovery blockquote{border-left:2px solid var(--line);padding:4px 0 4px 26px;font-size:clamp(20px,2vw,25px);line-height:1.5}
.discovery-stage.full-bleed .discovery blockquote{border-color:currentColor}
.meaning{background:var(--surface);color:var(--ink);padding:clamp(24px,4vw,44px);margin:28px 0;border-radius:16px;border:1px solid var(--line)}
.meaning summary{list-style:none;cursor:pointer;margin:0}
.meaning summary::-webkit-details-marker{display:none}
.meaning summary span,.meaning summary small{display:block;font-size:12px;letter-spacing:.1em;font-weight:600;opacity:.8}
.meaning summary strong{display:block;font-size:clamp(27px,3vw,42px);font-weight:500;letter-spacing:-.035em;line-height:1.15;margin:16px 0}
.evidence-ribbon{padding:24px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:24px 0}
.evidence-ribbon blockquote{font-size:20px;margin:12px 0}
.review-anchor{font-size:24px;margin-top:24px}
/* Review / keep flow */
.review-card{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(24px,3.5vw,44px);box-shadow:0 18px 44px -30px rgba(15,35,25,.35)}
.review-card .review-anchor{border-left:2px solid var(--line);padding-left:22px}
/* Saved / outcomes */
.record{max-width:680px;padding:32px 0;border-top:1px solid var(--ink)}
.record h2{font-size:clamp(32px,3vw,42px);font-weight:500}
.outcome-hero{padding:clamp(28px,5vw,64px);background:var(--panel);color:var(--panel-ink);margin-bottom:44px;position:relative;overflow:hidden;border-radius:24px}
.outcome-hero:after{content:"";position:absolute;right:5%;top:4%;width:120px;height:120px;background:radial-gradient(closest-side,var(--glow),transparent 70%)}
.outcome-hero h1,.outcome-hero p{position:relative;z-index:1;max-width:740px}
.outcome-section{padding:26px 0 32px;border-top:1px solid var(--line)}
.outcome-section .record{max-width:850px;background:var(--surface);border:1px solid var(--line);border-top:3px solid var(--green);padding:clamp(22px,3vw,36px);margin:24px 0;border-radius:16px}
/* Entry continuity */
.hero{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(48px,8vw,120px);align-items:start;padding-top:clamp(20px,4vh,44px)}
.hero h1{font-weight:500;line-height:1;letter-spacing:-.065em;font-size:clamp(52px,7vw,88px)}
.intro .lede{font-size:clamp(21px,2vw,27px);line-height:1.45}
.intake{display:grid;gap:18px;align-content:start}
.intake section{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:clamp(20px,2.5vw,28px);box-shadow:0 18px 44px -30px rgba(15,35,25,.35)}
.intake h2{font-size:22px;margin:0 0 6px}
.paste-entry summary{font-size:18px;font-weight:700;cursor:pointer}
.narrow{max-width:850px}
.wide{max-width:1050px}
.context details{border:1px solid var(--line);border-radius:12px;padding:12px 16px;background:var(--surface)}
.context pre{white-space:pre-wrap;font:13px/1.6 ui-monospace,monospace}
.candidate-quote{margin:28px 0}
.candidate-quote blockquote{margin-bottom:8px}
.candidate-quote figcaption{color:var(--muted);font-size:14px}
/* Reveal motion */
@media(prefers-reduced-motion:no-preference){
.reveal-enter .reveal-label{animation:reveal-label 380ms ease-out both}
.reveal-enter .discovery h2{animation:reveal-title 520ms cubic-bezier(.2,.7,.2,1) both}
.reveal-enter .portrait .fragment{animation:reveal-label 500ms ease-out both}
.reveal-enter .discovery-stage.full-bleed{animation:reveal-title 600ms cubic-bezier(.2,.7,.2,1) both}
@keyframes reveal-label{from{opacity:.65;transform:translateY(6px)}to{opacity:1;transform:none}}
@keyframes reveal-title{from{opacity:.72;transform:translateY(14px)}to{opacity:1;transform:none}}
}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
@media(max-width:1100px){.shell.immersive{grid-template-columns:minmax(0,1fr);gap:28px}.portrait{position:static;max-height:none}.discovery-map{grid-template-columns:1fr}}
@media(max-width:700px){main{padding:24px 18px 80px}.hero{grid-template-columns:1fr;gap:28px}.brand .lockup{width:min(220px,62vw)}.brand .lockup .ym{height:30px}.brand .lockup .realize{height:18px}.question{font-size:clamp(22px,5.6vw,28px)}.composer{position:sticky;bottom:0;padding-bottom:max(16px,env(safe-area-inset-bottom))}.discovery-stage.full-bleed{padding:28px 22px;border-radius:18px}.portrait{padding:20px 18px}.signal blockquote{font-size:20px}footer{flex-direction:column;align-items:flex-start;gap:12px}.foot-byline{border-left:0;border-top:1px solid var(--line);padding-left:0;padding-top:12px;max-width:100%}}
@media print{.source-anchor{position:static}.discovery-map{display:block}.discovery-stage.full-bleed{color:#222;background:#fff;border:1px solid #555}}
/* Phase 2: compact portrait, recognition-first reveal, connection composition */
.portrait-card summary{cursor:pointer;list-style:none;display:grid;gap:8px}
.portrait-card summary::-webkit-details-marker{display:none}
.portrait-card summary strong{font-size:15px}
.portrait-card .ready{display:inline-block;background:var(--blue);color:var(--on);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700;width:fit-content}
.portrait-card .portrait-body{margin-top:14px}
.trail{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:8px}
.trail li details{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:10px 14px}
.trail summary{font-size:13px;color:var(--muted);cursor:pointer}
.trail blockquote{margin:8px 0 0;font-size:15px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.trail details[open] blockquote{-webkit-line-clamp:unset}
.recognition-headline{font-size:clamp(30px,3.6vw,46px);line-height:1.08;letter-spacing:-.04em;text-wrap:balance;overflow-wrap:anywhere;max-width:20ch;scroll-margin-top:96px}
.recognition h1{scroll-margin-top:96px}
.question,.signal,.connection-stage h1{scroll-margin-top:96px;scroll-margin-bottom:24px}
.outcome-hero .eyebrow{background:transparent;color:inherit;border-color:currentColor}
.outcome-hero .lede{color:var(--panel-mute)}
.outcome-hero.personal h1{font-size:clamp(32px,4vw,54px);letter-spacing:-.045em;text-wrap:balance;overflow-wrap:anywhere}
.connection-stage h1{font-size:clamp(30px,3.6vw,46px);letter-spacing:-.04em;text-wrap:balance;overflow-wrap:anywhere;max-width:22ch}
.connection-pair{position:relative}
.connection-pair:after{content:"✦";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);background:var(--ink);color:var(--bg);width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;box-shadow:0 8px 24px -12px rgba(15,35,25,.5)}
.exp-full summary{cursor:pointer}
.exp-full summary span{font-size:13px;color:var(--muted);text-decoration:underline}
.keep-preview{font-size:15px;line-height:1.6;max-width:62ch;margin:22px 0 0;opacity:.92}
.keep-preview span{display:block;font-size:12px;letter-spacing:.1em;font-weight:700;opacity:.7;margin-bottom:6px}
@media(max-width:1100px){.connection-pair:after{display:none}}
.recognition-action{font-size:clamp(19px,2vw,24px);line-height:1.5;max-width:62ch;margin:22px 0}
.recognition-action span{display:block;font-size:12px;letter-spacing:.1em;font-weight:700;opacity:.7;margin-bottom:8px}
.recognition-quote{background:var(--surface);color:var(--ink);border-radius:16px;padding:clamp(20px,3vw,32px);max-width:640px;margin:0 0 22px}
.recognition-quote blockquote{margin:0;font-size:clamp(19px,2vw,23px);line-height:1.5}
.recognition-quote figcaption{font-size:13px;color:var(--muted);margin-top:10px}
.challenge-note{font-size:15px;opacity:.85;max-width:62ch}
.recognition-decide{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0 8px}
.recognition-decide form{margin:0}
.evidence{border-top:1px solid currentColor;margin-top:28px;padding-top:16px;max-width:760px}
.evidence summary{cursor:pointer;font-weight:700;font-size:17px}
.evidence h3{margin:26px 0 10px}
.evidence blockquote{border-left:2px solid currentColor;padding:4px 0 4px 22px;font-size:19px;line-height:1.55;margin:12px 0}
.evidence-material{font-size:15px;max-height:220px;overflow:auto;white-space:pre-wrap}
.connection-stage .connection-meaning{font-size:clamp(20px,2vw,25px);max-width:62ch}
.connection-pair{display:grid;grid-template-columns:1fr 1fr;gap:clamp(18px,3vw,32px);margin:28px 0}
.connection-exp{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:clamp(20px,2.5vw,30px);margin:0}
.connection-exp blockquote{margin:14px 0;font-size:18px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}
.connection-exp .connection-action{color:var(--muted);font-size:15px}
.connection-why{background:var(--panel);color:var(--panel-ink);border-radius:16px;padding:clamp(22px,3vw,36px);margin:28px 0;max-width:900px}
.connection-why h2{font-size:clamp(26px,2.6vw,36px);font-weight:500;margin:0 0 12px}
.connection-why p{margin:0;max-width:68ch;font-size:18px;line-height:1.6}
.connection-why:before{content:"";display:block;width:64px;height:4px;background:var(--green);margin-bottom:18px;border-radius:2px}
.connection-limits{border-top:1px solid var(--line);margin-top:8px;padding-top:14px;max-width:900px}
.connection-limits summary{cursor:pointer;font-weight:700}
.kept-first .kept-card{background:var(--surface);border:1px solid var(--line);border-top:3px solid var(--green);border-radius:16px;padding:clamp(20px,3vw,32px);margin:20px 0;max-width:850px}
.kept-first .kept-claim{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:19px;line-height:1.6}
.kept-connection{background:var(--panel);color:var(--panel-ink);border-radius:16px;padding:clamp(20px,3vw,32px);margin:20px 0;max-width:850px}
.kept-connection .eyebrow{background:transparent;color:inherit;border-color:currentColor}
.kept-connection p{margin:0}
.lead{display:block;width:100%;text-align:left;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:16px;padding:18px 22px;margin:12px 0;box-shadow:0 18px 44px -30px rgba(15,35,25,.35);font-weight:400}
.lead:hover{transform:translateY(-2px);border-color:var(--blue)}
.lead strong{display:block;font-size:19px;line-height:1.4;margin-bottom:6px}
.lead span{display:block;color:var(--muted);font-size:15px;line-height:1.55;font-weight:400}
@media(max-width:1100px){.shell.immersive{display:flex;flex-direction:column}.shell.immersive .stage{order:-1;width:100%;max-width:100%}.shell.immersive .portrait{order:2;width:100%;position:static;max-height:none}.connection-pair{grid-template-columns:1fr}}
.recognition-decide .secondary{color:var(--panel-ink);border-color:var(--panel-mute)}
@media(prefers-reduced-motion:no-preference){.reveal-enter .recognition-headline{animation:reveal-title 520ms cubic-bezier(.2,.7,.2,1) both}.reveal-enter .connection-exp:nth-child(2){animation:reveal-title 520ms 120ms cubic-bezier(.2,.7,.2,1) both}}
</style></head><body><header><div class="brand"><span class="lockup" role="img" aria-label="YourMove Realize"><img class="logo-light ym" src="/identity/yourmove-wordmark-navigation-light.png" alt="" aria-hidden="true" width="768" height="268"><img class="logo-dark ym" src="/identity/yourmove-wordmark-navigation-dark.png" alt="" aria-hidden="true" width="768" height="268"><svg class="realize" viewBox="0 0 168 32" aria-hidden="true" focusable="false"><text x="4" y="30" font-family="Jost,'Avenir Next','Segoe UI',sans-serif" font-size="32" font-weight="800" letter-spacing="-0.5" style="fill:var(--green-deep)">Realize</text><path d="M0 -8 L2 -2 L8 0 L2 2 L0 8 L-2 2 L-8 0 L-2 -2 Z" transform="translate(140,10)" style="fill:var(--green-deep)"/><path d="M0 -6 L1.5 -1.5 L6 0 L1.5 1.5 L0 6 L-1.5 1.5 L-6 0 L-1.5 -1.5 Z" transform="translate(154,18)" style="fill:var(--blue)"/></svg></span></div><button class="theme no-print" id="theme" type="button">Theme</button></header><main id="app" tabindex="-1">
{{if .Notice}}<div class="notice" role="alert">{{.Notice}}</div>{{end}}
{{if and .State.Responses (ne .Stage "conversation") (ne .Stage "reveal") (ne .Stage "review") (ne .Stage "takeaway")}}<details class="conversation-recap" aria-label="Conversation history"><summary>Conversation history</summary>{{range .State.Responses}}<div class="message realize"><small>Realize</small><p>{{.Question}}</p></div><div class="message user"><small>You</small><p>{{.Source.Text}}</p></div>{{end}}</details>{{end}}
{{if eq .Stage "welcome"}}<div class="hero"><section class="intro"><p class="eyebrow">YOURMOVE REALIZE</p><h1>You did more than you think.</h1><p class="lede">Realize helps you recognize something meaningful about your own experience. Tell us about your work. We will ask a few questions to uncover the skills behind it.</p><p class="muted">A viewer can see the point in seconds: your words stay yours, and any interpretation is labeled and yours to review.</p></section><div class="intake"><section><h2>Upload a resume</h2><p class="muted">A PDF or Word document, up to 10 MiB.</p><form action="/upload" method="post" enctype="multipart/form-data"><label for="file">Choose a file</label><input id="file" name="resume" type="file" accept=".pdf,.docx" required><div><button type="submit">Upload and preview</button></div></form></section><section><details class="paste-entry" open><summary>Or paste your experience</summary><p class="muted">A role, project, resume bullet, or a few words about your work.</p><form action="/paste" method="post"><label for="career_text">Your experience</label><textarea id="career_text" name="career_text" rows="7" required placeholder="Paste or describe something you have worked on"></textarea><div class="actions"><button type="submit">Preview text</button></div></form></details></section></div></div>
{{else if eq .Stage "preview"}}<div class="narrow"><h2>Take a look before we begin.</h2>{{if eq .InputKind "paste"}}<p class="lede">This is the text you supplied.</p>{{else}}<p class="lede">This text was extracted locally from {{.Filename}}.</p>{{end}}{{if .Truncated}}<div class="notice">Only the first 8,000 bytes shown here will be sent and considered. The rest has not been analyzed.</div>{{end}}<div class="preview">{{.State.Resume.Text}}</div><p style="margin-top:24px">When you begin, this text and your subsequent answers are sent to Baseten for AI inference. Your account is not independently verified. Session data is held in memory while the server runs.</p><form action="/begin" method="post" class="infer"><label class="voice-choice" for="interviewer-voice">Choose your interviewer voice<select id="interviewer-voice" name="voice"><option value="feminine" {{if ne .Voice "masculine"}}selected{{end}}>Laura</option><option value="masculine" {{if eq .Voice "masculine"}}selected{{end}}>Adrian</option></select></label><small>Choose the voice for your conversation.</small><div class="actions">{{if eq .InputKind "paste"}}<button type="submit" name="approach" value="focused">Explore this experience</button><button class="secondary" type="submit" name="approach" value="leads">Choose a starting point</button>{{else}}<button type="submit">Begin discovery</button>{{end}}</div><p class="waiting" role="status">Requesting a starting point from Baseten</p></form><form action="/reset" method="post"><button class="link">Start over</button></form></div>
{{else if eq .Stage "leads"}}<div class="narrow"><h2>Where would you like to begin?</h2><p class="lede">Choose a starting point based on what you shared.</p>{{range .State.Leads}}{{if ne .ID $.SkipLead}}<form action="/select" method="post" class="infer"><button class="lead" name="lead" value="{{.ID}}"><strong>{{.Title}}</strong><span>{{.Why}}</span></button><p class="waiting" role="status">Requesting a question from Baseten</p></form>{{end}}{{end}}{{if .SkipLead}}<form action="/explore" method="post"><label for="new-focus">Or choose another experience</label><input id="new-focus" name="focus" maxlength="120" required><button>Explore this experience</button></form>{{end}}{{if .Discoveries}}<form action="/collection" method="post"><button class="link">Return to discoveries</button></form>{{end}}</div>
{{else if eq .Stage "paused"}}<div class="narrow"><h2>{{if .EndRequested}}We will stop here.{{else}}Let us leave this topic here.{{end}}</h2><p>Your responses are saved in this session.</p>{{if .State.Proposal}}<p>A possible discovery is available for your review.</p><form action="/reveal" method="post"><button>See the discovery</button></form><form action="/discard-pending" method="post"><button class="link">Discard this suggestion</button></form>{{end}}{{if and (not .EndRequested) (not .State.Proposal)}}<form action="/explore" method="post"><label for="next-focus">Choose another experience{{if .OriginalLeads}} (optional){{end}}</label><input id="next-focus" name="focus" maxlength="120" {{if not .OriginalLeads}}required{{end}}><button>Explore another experience</button></form>{{end}}{{if .Discoveries}}<form action="/collection" method="post"><button class="secondary">Return to discoveries</button></form><form action="/takeaway" method="post"><button class="secondary">See your takeaway</button></form>{{end}}{{if and .EndRequested (not .State.Proposal) (not .Discoveries)}}<p>You ended with no reviewed discoveries, so there is nothing to summarize. No further questions will be asked.</p><form action="/takeaway" method="post"><button class="secondary">See your summary</button></form>{{end}}</div>
{{else if eq .Stage "conversation"}}<div class="shell immersive"><aside class="portrait" aria-label="Living Portrait"><details class="portrait-card" id="portrait-detail"><summary><span class="eyebrow">LIVING PORTRAIT</span><strong>{{len .State.Responses}} moments · {{len .Discoveries}} kept</strong>{{if .State.Proposal}}<b class="ready">Discovery ready</b>{{end}}</summary><div class="portrait-body"><h2>What your words are revealing</h2><p class="portrait-purpose">Nothing here is scored. Only what your words can support appears.</p><p class="portrait-focus">{{if .State.SelectedLead}}Exploring {{.State.SelectedLead.Title}}{{else}}Exploring your experience{{end}}</p>{{if .State.Responses}}<ol class="trail">{{range .State.Responses}}<li><details><summary><span>{{.Source.ID}}</span> · your exact words</summary><blockquote>{{.Source.Text}}</blockquote></details></li>{{end}}</ol>{{else}}{{if .Discoveries}}<p class="muted portrait-empty">A new thread. Your kept discoveries are below; answer one question and an exact fragment of your new words will appear here.</p>{{else}}<p class="muted portrait-empty">Your portrait is empty. Answer one question and an exact fragment of your words will appear here. Nothing is invented.</p>{{end}}{{end}}{{if .Discoveries}}<div class="portrait-kept"><h3>Kept by you</h3><ul>{{range .Discoveries}}<li><strong>{{.Title}}</strong><span>{{.SourceID}} · reviewed</span></li>{{end}}</ul></div>{{end}}{{if .State.Proposal}}<p class="portrait-pending">A possible discovery awaits your review. Nothing is kept without you.</p>{{end}}</div></details></aside><div class="stage"><section><p class="kicker">{{if .State.SelectedLead}}Exploring {{.State.SelectedLead.Title}}{{else}}Exploring your experience{{end}}</p>{{if .State.Responses}}<details class="history" aria-label="Conversation history"><summary>Your conversation · {{len .State.Responses}} responses</summary><div>{{range .State.Responses}}<div class="turn"><div class="message realize"><small>Realize</small><p>{{.Question}}</p></div><div class="message user"><small>You</small><p>{{.Source.Text}}</p></div></div>{{end}}</div></details>{{end}}{{if .State.Proposal}}<div class="signal">{{if .Progressive}}<p class="eyebrow">SOMETHING WORTH RECOGNIZING</p><h3>Potential strength: {{.Progressive.Strength}}</h3><p>What you shared may suggest this strength. It is an interpretation for you to consider.</p><p><strong>What you shared</strong></p><blockquote>{{.Progressive.Quote}}</blockquote>{{else}}<p class="eyebrow">READY TO REVIEW</p><h3>Here is a possible discovery.</h3><blockquote>{{.State.Proposal.Quote}}</blockquote>{{end}}<form method="post" action="/reveal"><button class="link">See the discovery</button></form></div>{{end}}{{if .State.Question}}{{if lt (len .State.Responses) 6}}<div class="question-focus"><div class="message realize question"><small>Realize asks</small><p>{{.State.Question}}</p><div class="voice-controls"><button type="button" class="secondary speak-question">Listen to question</button></div><span class="playback-status" role="status"></span></div></div><form action="/answer" method="post" class="infer composer"><label for="answer">Your response <small> · Enter to send, Shift+Enter for a new line</small></label><textarea id="answer" name="answer" maxlength="2000" rows="2" required placeholder="What happened? You can also correct anything I misunderstood."></textarea><div class="actions"><button type="button" class="secondary record-answer">Record answer</button><button type="submit">Continue</button></div><p class="voice-status" role="status">Record an answer, then review it before sending. Audio is sent to Deepgram for transcription.</p><p class="waiting" role="status">Sending your answer to Baseten for the next question</p></form>{{else}}<p class="notice">You have reached the six-response limit for this conversation. {{if not .State.Proposal}}There is not enough supported detail for a discovery yet.{{end}}</p>{{end}}{{else}}<p>Your answers are saved in this session.</p><form action="/retry" method="post" class="infer"><button>Retry the request</button><p class="waiting" role="status">Requesting a question from Baseten</p></form>{{end}}{{if .Discoveries}}<form action="/collection" method="post"><button class="link">Return to discoveries</button></form>{{end}}</section><aside class="context"><details id="context"><summary>Your original material</summary><div><pre>{{.State.Resume.Text}}</pre>{{if .Truncated}}<small>Only this excerpt was analyzed.</small>{{end}}</div></details></aside></div></div>
{{else if eq .Stage "reveal"}}<div class="shell immersive"><aside class="portrait" aria-label="Living Portrait"><details class="portrait-card" id="portrait-detail"><summary><span class="eyebrow">LIVING PORTRAIT</span><strong>{{len .State.Responses}} moments · {{len .Discoveries}} kept</strong><b class="ready">Discovery ready</b></summary><div class="portrait-body"><h2>A moment worth checking</h2><p class="portrait-purpose">This reading is drawn only from your recorded words.</p>{{if .State.Responses}}<ol class="trail">{{range .State.Responses}}<li><details><summary><span>{{.Source.ID}}</span> · your exact words</summary><blockquote>{{.Source.Text}}</blockquote></details></li>{{end}}</ol>{{end}}{{if .Discoveries}}<div class="portrait-kept"><h3>Kept by you</h3><ul>{{range .Discoveries}}<li><strong>{{.Title}}</strong><span>{{.SourceID}} · reviewed</span></li>{{end}}</ul></div>{{end}}</div></details></aside><div class="stage stage-wide"><div class="discovery-stage recognition full-bleed"><p class="eyebrow reveal-label">A POSSIBLE DISCOVERY · AI INTERPRETATION</p><h1 class="recognition-headline">{{if .State.Proposal.Headline}}{{.State.Proposal.Headline}}{{else}}{{quoteExcerpt .State.Proposal.Title}}{{end}}</h1><p class="recognition-action"><span>WHAT REALIZE SEES YOU DOING</span>{{.State.Proposal.Experience}}</p><figure class="recognition-quote"><blockquote>&ldquo;{{if longQuote .State.Proposal.Quote}}{{quoteExcerpt .State.Proposal.Quote}}…{{else}}{{.State.Proposal.Quote}}{{end}}&rdquo;</blockquote><figcaption>{{.State.Proposal.SourceID}} · your exact words</figcaption></figure><p class="challenge-note">An AI reading of your account — challenge it or keep what fits. A matching quotation does not prove this conclusion.</p><p class="keep-preview"><span>YOU WOULD KEEP</span>&ldquo;{{.State.Proposal.Title}}&rdquo; — {{.State.Proposal.Claim}}</p><div class="recognition-decide"><form action="/keep" method="post"><input type="hidden" name="title" value="{{.State.Proposal.Title}}"><input type="hidden" name="experience" value="{{.State.Proposal.Experience}}"><input type="hidden" name="claim" value="{{.State.Proposal.Claim}}"><button type="submit">Keep this discovery</button></form><form action="/review" method="post"><button class="secondary" type="submit">Correct the wording</button></form><form action="/continue" method="post"><button class="secondary" type="submit">Keep talking</button></form></div><details class="evidence"><summary>Why Realize thinks so · inspect the evidence</summary><div><h3>The full quotation</h3><blockquote>{{.State.Proposal.Quote}}</blockquote><p><small>{{.State.Proposal.SourceID}} · complete cited quotation from your recorded account</small></p>{{if and .State.Proposal.Headline (ne .State.Proposal.Headline .State.Proposal.Title)}}<p><small>Display headline above; complete validated title: &ldquo;{{.State.Proposal.Title}}&rdquo;.</small></p>{{end}}{{if .State.Proposal.Supports}}<h3>Also in your words</h3>{{range .State.Proposal.Supports}}<blockquote>{{.Quote}}</blockquote><p><small>{{.SourceID}} · exact supporting statement</small></p>{{end}}{{end}}<h3>What remains open</h3>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p class="muted">No open questions identified.</p>{{end}}<h3>Your starting material</h3><blockquote class="evidence-material">{{.State.Resume.Text}}</blockquote></div></details></div></div>
{{else if eq .Stage "review"}}<div class="shell immersive"><aside class="portrait" aria-label="Living Portrait"><details class="portrait-card" id="portrait-detail"><summary><span class="eyebrow">LIVING PORTRAIT</span><strong>{{len .State.Responses}} moments · {{len .Discoveries}} kept</strong></summary><div class="portrait-body"><h2>Make it sound like what happened</h2><p class="portrait-purpose">Only you can say what is true. Edit the interpretation, keep your original words untouched.</p><ol class="trail">{{range .State.Responses}}<li><details{{if eq .Source.ID $.State.Proposal.SourceID}} open{{end}}><summary><span>{{.Source.ID}}</span>{{if eq .Source.ID $.State.Proposal.SourceID}} · cited source{{else}} · your exact words{{end}}</summary><blockquote>{{.Source.Text}}</blockquote></details></li>{{end}}</ol></div></details></aside><div class="stage"><div class="narrow review-card"><p class="eyebrow">REVIEW DISCOVERY</p><h2>Make it sound like what actually happened.</h2><blockquote class="review-anchor">{{.State.Proposal.Quote}}</blockquote><small>{{.State.Proposal.SourceID}} · original quotation, unchanged by your edits</small><p class="lede">Review the interpretation before keeping it. Your approval is not independent verification.</p><form method="post" action="/keep"><p class="muted">Edit the wording to reflect what you did and where your responsibility ended. Your original statements stay unchanged.</p><label for="title">Title</label><input id="title" name="title" maxlength="160" value="{{.State.Proposal.Title}}" required><label for="experience">What you did</label><textarea id="experience" name="experience" maxlength="1500" required>{{.State.Proposal.Experience}}</textarea><label for="claim">What this suggests</label><textarea id="claim" name="claim" maxlength="1500" required>{{.State.Proposal.Claim}}</textarea><h3 style="margin-top:24px">What remains open</h3>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p class="muted">None identified by the model.</p>{{end}}<details><summary>Recorded conversation and cited statement</summary><div>{{range .State.Responses}}<blockquote>{{.Source.Text}}</blockquote><small>{{.Source.ID}}{{if eq .Source.ID $.State.Proposal.SourceID}} · cited source{{end}}</small>{{end}}<p><small>Exact cited passage: &ldquo;{{.State.Proposal.Quote}}&rdquo;. Edits do not change the original statements.</small></p></div></details><div class="actions"><button>Accept and keep this wording</button></div></form><form method="post" action="/reject"><button class="link">Discard suggestion and continue talking</button></form></div></div></div>
{{else if eq .Stage "saved"}}<div class="shell immersive"><aside class="portrait" aria-label="Living Portrait"><details class="portrait-card" id="portrait-detail"><summary><span class="eyebrow">LIVING PORTRAIT</span><strong>{{len .Discoveries}} kept · {{len .State.Responses}} moments</strong></summary><div class="portrait-body"><h2>Your portrait so far</h2><p class="portrait-purpose">Kept discoveries, in your reviewed wording. Open any item to inspect its source.</p>{{if .Discoveries}}<div class="portrait-kept"><h3>Kept by you</h3><ul>{{range .Discoveries}}<li><details><summary><strong>{{.Title}}</strong><span>{{.SourceID}} · reviewed</span></summary><blockquote>{{.Quote}}</blockquote></details></li>{{end}}</ul></div>{{else}}<p class="muted portrait-empty">Nothing kept yet.</p>{{end}}</div></details></aside><div class="stage stage-wide"><div class="wide"><p class="eyebrow">KEPT BY YOU · {{len .Discoveries}} DISCOVERIES</p><h2>Your discoveries.</h2><p class="lede">Discoveries you have reviewed, with their sources and open questions.</p>{{range .Discoveries}}{{$d := .}}<article class="record"><h3>{{.Title}}</h3><p>{{.Experience}}</p><p>{{.Claim}}</p><details><summary>Starting material, conversation and open questions</summary><div><h3>Starting material</h3><blockquote>{{.OriginalMaterial}}</blockquote><h3>Your recorded statements</h3>{{range $d.Responses}}<blockquote>{{.Source.Text}}</blockquote><small>{{.Source.ID}}{{if eq .Source.ID $d.SourceID}} · cited source{{end}}</small>{{end}}<p><small>Exact cited passage ({{$d.SourceID}}): &ldquo;{{$d.Quote}}&rdquo;. Edits do not change the original statements.</small></p>{{if $d.Supports}}<p><small>Supporting statements:</small></p><ul>{{range $d.Supports}}<li><small>{{.SourceID}} · supporting statement: &ldquo;{{.Quote}}&rdquo;</small></li>{{end}}</ul>{{end}}{{if $d.Unresolved}}<p>Still open:</p><ul>{{range $d.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{end}}</div></details><form action="/edit" method="post"><button class="link" name="id" value="{{.ID}}">Review or correct wording</button></form></article>{{end}}{{if .Synthesis}}{{range .Synthesis.Connections}}<article class="insight"><p class="muted">A possible connection across your experiences</p><h2>{{.Capability}}</h2><p>{{.Interpretation}}</p><p>{{.Relationship}}</p><form action="/show-connections" method="post"><button class="link">Explore this interpretation and its sources</button></form></article>{{end}}{{end}}<div class="actions">{{if .State.Proposal}}<p class="notice">A possible discovery is still awaiting your review.</p><form action="/reveal" method="post"><button>See the discovery</button></form>{{end}}{{if lt (len .Discoveries) 4}}<form action="/explore" method="post" class="infer"><label for="focus">What else would you like to explore? <small>(optional)</small></label><input id="focus" name="focus" maxlength="120" placeholder="Another responsibility or experience"><button>Explore another experience</button><p class="waiting" role="status">Requesting a question from Baseten</p></form>{{end}}{{if ge (len .Discoveries) 2}}<form action="/connections" method="post" class="infer"><button class="secondary">Find connections</button><p class="waiting" role="status">Asking Baseten to examine the reviewed experiences</p></form>{{end}}<form action="/takeaway" method="post" class="infer"><button>See your takeaway</button><p class="waiting" role="status">Putting your takeaway together</p></form></div><p class="muted">Saved for this session only.</p></div></div></div>
{{else if eq .Stage "connections"}}<div class="wide connection-stage"><p class="eyebrow">A POSSIBLE CONNECTION · AI INTERPRETATION</p>{{if .Synthesis.Connections}}{{range .Synthesis.Connections}}<h1>{{.Capability}}</h1><p class="lede connection-meaning">{{.Interpretation}}</p><div class="connection-pair">{{range .Supports}}<figure class="connection-exp"><p class="eyebrow">DISCOVERY {{.EvidenceID}}</p>{{if longQuote .Quote}}<details class="exp-full"><summary>&ldquo;{{quoteExcerpt .Quote}}…&rdquo; <span>read full</span></summary><blockquote>&ldquo;{{.Quote}}&rdquo;</blockquote></details>{{else}}<blockquote>&ldquo;{{.Quote}}&rdquo;</blockquote>{{end}}<p class="connection-action">{{.Action}}</p><form action="/edit" method="post"><button class="link" name="id" value="{{.EvidenceID}}">Inspect or correct this discovery</button></form></figure>{{end}}</div><div class="connection-why"><h2>Why this pattern could matter</h2><p>{{.Relationship}}</p></div><details class="connection-limits"><summary>Limits, careful language, and control</summary><div><h3>What this does not establish</h3><ul>{{range .Limitations}}<li>{{.}}</li>{{end}}</ul><h3>Language to review carefully</h3><p class="quote">{{.CandidateUse}}</p><p class="muted">Check the wording against what happened before using it.</p>{{if .FollowUp}}<p class="muted">A question to consider: {{.FollowUp}}</p>{{end}}<details><summary>Challenge this connection</summary><div><p>If the experiences are accurate but this relationship is wrong, withdraw it. To correct an experience, return to your portrait and review that discovery.</p><form action="/challenge" method="post"><input type="hidden" name="connection_id" value="{{.ID}}"><label>Why does this interpretation miss the mark?</label><textarea name="challenge" maxlength="2000" required></textarea><button class="secondary">Withdraw this interpretation</button></form></div></details></div></details>{{end}}{{else if not .PreviousInterpretation}}<div class="insight"><h2>No defensible connection emerged yet.</h2><p>Try adding more detail, or explore another experience.</p></div>{{end}}{{if .PreviousInterpretation}}<div class="notice"><strong>Withdrawn interpretation</strong><p>{{.PreviousInterpretation}}</p><strong>Your perspective</strong><p>{{.Challenge}}</p><small>This interpretation is no longer part of your current portrait.</small></div>{{end}}<div class="actions"><form action="/collection" method="post"><button class="secondary">Back to discoveries</button></form><form action="/takeaway" method="post"><button>View your takeaway</button></form></div></div>
{{else if eq .Stage "takeaway"}}<div class="wide">{{if .Outcomes}}<div class="outcome-hero personal"><p class="eyebrow">YOUR PERSONAL TAKEAWAY</p>{{with index .Discoveries 0}}<h1>{{.Title}}</h1>{{end}}<p class="lede">You kept {{len .Discoveries}} {{if eq (len .Discoveries) 1}}discovery{{else}}discoveries{{end}} — here is what {{if eq (len .Discoveries) 1}}it says{{else}}they say{{end}}, in your approved wording.{{if .Synthesis}} Plus a possible connection across your experiences.{{end}}</p></div><section class="outcome-section kept-first"><h2>What you chose to keep</h2><p>Your reviewed discoveries, in your approved wording.{{if .Synthesis}} Plus a possible connection across your experiences.{{end}}</p>{{range .Discoveries}}<article class="kept-card"><h3>{{.Title}}</h3><p class="kept-claim">{{.Claim}}</p><p><small>{{if .Unresolved}}{{len .Unresolved}} open questions{{else}}No open questions{{end}} · source {{.SourceID}}</small></p></article>{{else}}<p class="muted">No kept discoveries yet.</p>{{end}}{{if .Synthesis}}{{range .Synthesis.Connections}}<article class="kept-connection"><p class="eyebrow">A POSSIBLE CONNECTION</p><h3>{{.Capability}}</h3><p>{{.Interpretation}}</p></article>{{end}}{{end}}</section><section class="outcome-section"><h2>Consider adding to your resume</h2><p>Starting points to edit and check against what you did. Suggestions can get details wrong.</p>{{range .Outcomes.Resume}}<article class="record"><h3>{{.Title}}</h3><p>Start with your own words, then edit them for your resume.</p><label>Starting wording from your account</label><textarea rows="3" aria-label="Edit suggested resume wording">{{.Wording}}</textarea><div class="no-print"><button type="button" class="secondary copy-outcome">Copy wording</button><p class="copy-status muted" role="status"></p></div><details><summary>See your supporting statement</summary><blockquote>{{.Quote}}</blockquote><small>{{.SourceID}} · discovery {{.EvidenceID}}</small></details><form action="/edit" method="post"><button class="link" name="id" value="{{.EvidenceID}}">Review or correct this discovery</button></form></article>{{else}}<p>No sufficiently supported resume suggestion emerged yet.</p>{{end}}</section><section class="outcome-section"><h2>Strengths you may not recognize</h2><p>Possible interpretations, not established facts. Check each one against your words.</p>{{range .Outcomes.Strengths}}<article class="record"><h3>{{.Title}}</h3><p>Your experience may suggest {{.Title}}. Consider whether this fits you.</p><figure class="candidate-quote"><blockquote>{{.Quote}}</blockquote><figcaption>{{.SourceID}} · your supporting statement</figcaption></figure><form action="/edit" method="post"><button class="link" name="id" value="{{.EvidenceID}}">Review or correct this discovery</button></form></article>{{else}}<p>No additional strength could be identified from this account yet.</p>{{end}}</section><section class="outcome-section"><h2>Possibilities worth exploring</h2><p>Ideas for growth, not claims that you already have these qualifications.</p>{{range .Outcomes.Possibilities}}<article class="record"><h3>{{.Title}}</h3><p>This could be an area to explore or develop, inspired by what you shared.</p><figure class="candidate-quote"><blockquote>{{.Quote}}</blockquote><figcaption>{{.SourceID}} · your supporting statement</figcaption></figure><form action="/edit" method="post"><button class="link" name="id" value="{{.EvidenceID}}">Review or correct this discovery</button></form></article>{{else}}<p>No specific possibility emerged from this account yet.</p>{{end}}</section><div class="outcome-finish"><h2>Your story is yours to tell.</h2><p>Keep what feels true, shape the words in your own voice, and take the next step that feels right for you.</p></div>{{else if .Discoveries}}<p class="notice">The additional outcome ideas could not be generated. Your reviewed discoveries are available below; return to discoveries and try again.</p>{{else}}<p class="notice">You finished without keeping a reviewed discovery, so there is no summary to show. Your responses stay saved in this session, and nothing further will be asked.</p>{{end}}{{if .Discoveries}}<details class="outcome-archive"><summary>Your reviewed discoveries and open questions</summary><div><p class="muted">YourMove Realize · takeaway</p><h1>Your discoveries.</h1><p class="lede">Your reviewed discoveries and their sources. They have not been independently verified.</p>{{range .Discoveries}}{{$d := .}}<article class="record"><h2>{{.Title}}</h2>{{if $d.Unresolved}}<p class="notice">Open questions remain.</p>{{else}}<p class="notice">No open questions identified.</p>{{end}}<h3>Your contribution</h3><p class="reviewed-experience">{{.Experience}}</p><h3>What it may show</h3><p>{{.Claim}}</p>{{if .ReviewChanges}}<details><summary>See what you changed</summary>{{range .ReviewChanges}}<p><small>Before your review</small></p><p>{{.Before.Title}}</p><p>{{.Before.Experience}}</p><p>{{.Before.Claim}}</p><p><small>Wording you accepted</small></p><p>{{.After.Title}}</p><p>{{.After.Experience}}</p><p>{{.After.Claim}}</p>{{end}}</details>{{end}}<div class="no-print"><button type="button" class="secondary copy-reviewed">Copy contribution</button><p class="copy-status muted" role="status"></p><small>Adapt this wording before using it.</small></div><figure class="candidate-quote"><blockquote>{{$d.Quote}}</blockquote><figcaption>{{$d.SourceID}} · exact quotation from your account</figcaption></figure>{{if $d.Unresolved}}<h3>Still open</h3><ul>{{range $d.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{end}}<details><summary>Supporting statements and starting material</summary><div><h3>Starting material</h3><blockquote>{{.OriginalMaterial}}</blockquote>{{range $d.Responses}}<blockquote>{{.Source.Text}}</blockquote><small>{{.Source.ID}}{{if eq .Source.ID $d.SourceID}} · cited passage supporting this claim{{else}} · recorded statement{{end}}</small>{{end}}{{if $d.Supports}}<p><small>Supporting statements:</small></p><ul>{{range $d.Supports}}<li><small>{{.SourceID}} · supporting statement: &ldquo;{{.Quote}}&rdquo;</small></li>{{end}}</ul>{{end}}</div></details></article>{{end}}{{if .Synthesis}}{{range .Synthesis.Connections}}<article class="insight"><h2>{{.Capability}}</h2><p>{{.Interpretation}}</p><p>{{.Relationship}}</p><h3>Model-suggested words to review</h3><p class="quote">{{.CandidateUse}}</p><p class="muted">Check this language against your account before using it; the model can overstate outcomes.</p><h3>Limits</h3><ul>{{range .Limitations}}<li>{{.}}</li>{{end}}</ul>{{if .FollowUp}}<p class="muted">A question to consider: {{.FollowUp}}</p>{{end}}</article>{{end}}{{end}}{{if .Challenge}}<h3>Your perspective on the connection</h3><p>{{.Challenge}}</p>{{end}}<h2>Next actions</h2><p class="muted">Use these descriptions as a starting point for your resume. Check any outcomes before including them.</p>{{range .Discoveries}}{{if .Unresolved}}<p>Revisit &ldquo;{{.Title}}&rdquo;:</p><ul>{{range .Unresolved}}<li>{{.}}</li>{{end}}</ul>{{end}}{{end}}{{if .Synthesis}}{{range .Synthesis.Connections}}{{if .FollowUp}}<p>A question to consider: {{.FollowUp}}</p>{{end}}{{end}}{{end}}</div></details>{{end}}<div class="actions no-print">{{if .Discoveries}}<button type="button" onclick="window.print()">Print or save as PDF</button><a class="button secondary" href="/download">Download JSON</a><form action="/collection" method="post"><button class="secondary">Back to discoveries</button></form>{{else}}<form action="/explore" method="post"><label for="empty-focus">Explore an experience <small>(optional)</small></label><input id="empty-focus" name="focus" maxlength="120" placeholder="Another responsibility or experience"><button>Explore an experience</button></form><form action="/reset" method="post"><button class="link">Start over</button></form>{{end}}</div></div>{{end}}
</main><footer><span class="foot-lockup" role="img" aria-label="YourMove Realize"><img class="logo-light ym-foot" src="/identity/yourmove-wordmark-navigation-light.png" alt="" aria-hidden="true" width="768" height="268"><img class="logo-dark ym-foot" src="/identity/yourmove-wordmark-navigation-dark.png" alt="" aria-hidden="true" width="768" height="268"><svg class="realize" viewBox="0 0 168 32" aria-hidden="true" focusable="false"><text x="4" y="30" font-family="Jost,'Avenir Next','Segoe UI',sans-serif" font-size="32" font-weight="800" letter-spacing="-0.5" style="fill:var(--green-deep)">Realize</text><path d="M0 -8 L2 -2 L8 0 L2 2 L0 8 L-2 2 L-8 0 L-2 -2 Z" transform="translate(140,10)" style="fill:var(--green-deep)"/><path d="M0 -6 L1.5 -1.5 L6 0 L1.5 1.5 L0 6 L-1.5 1.5 L-6 0 L-1.5 -1.5 Z" transform="translate(154,18)" style="fill:var(--blue)"/></svg></span><span class="foot-byline">Rediscover your strengths. Recognize your worth. Realize what is possible.</span></footer><script>
var sending=false;
function restoreDraft(root){try{var saved=JSON.parse(sessionStorage.getItem('realize-draft')||'null');var answer=(root||document).querySelector('#answer');var q=(root||document).querySelector('.question p');if(saved&&answer&&q&&saved.question===q.textContent){answer.value=saved.text;answer.style.height='auto';answer.style.height=Math.min(answer.scrollHeight,240)+'px'}}catch(e){}}
restoreDraft(document);
var playback=null,playbackAbort=null,playbackURL=null,playbackVersion=0;
function stopPlayback(){playbackVersion++;if(playbackAbort){playbackAbort.abort()}playbackAbort=null;if(playback){try{playback.pause()}catch(e){}playback=null}if(playbackURL){try{URL.revokeObjectURL(playbackURL)}catch(e){}playbackURL=null}if(window.speechSynthesis){try{window.speechSynthesis.cancel()}catch(e){}}var b=document.querySelector('.speak-question');if(b){b.textContent='Listen to question';b.dataset.playing='';var st=b.closest('.question');if(st){var ps=st.querySelector('.playback-status');if(ps)ps.textContent=''}}}
var questionAudioText='',questionAudioBlob=null,autoQuestionPlayback=false;
async function playQuestion(b,automatic){if(!b||!b.isConnected)return;if(!automatic)autoQuestionPlayback=true;stopPlayback();b.dataset.playing='yes';b.textContent='Stop listening';var st=b.closest('.question');var status=st?st.querySelector('.playback-status'):null;var q=st?st.querySelector('p').textContent:'';var version=playbackVersion;if(status)status.textContent=' Preparing audio';try{var blob=(q===questionAudioText&&questionAudioBlob)?questionAudioBlob:null;if(!blob){playbackAbort=new AbortController();var timer=setTimeout(function(){if(playbackAbort)playbackAbort.abort()},30000);try{var res=await fetch('/speech/question',{method:'POST',signal:playbackAbort.signal});if(!res.ok)throw new Error('audio');blob=await res.blob();if(version!==playbackVersion)return;questionAudioText=q;questionAudioBlob=blob}finally{clearTimeout(timer)}}if(version!==playbackVersion)return;playbackURL=URL.createObjectURL(blob);playback=new Audio(playbackURL);playback.onended=function(){if(version!==playbackVersion)return;stopPlayback()};await playback.play();if(status)status.textContent=' Playing Fish Audio.'}catch(err){if(version!==playbackVersion)return;if(err&&err.name==='NotAllowedError'){autoQuestionPlayback=false;stopPlayback();if(status)status.textContent='Tap Listen to hear this question.';return}if(window.speechSynthesis&&window.SpeechSynthesisUtterance){if(status)status.textContent='Using your browser default voice.';var u=new SpeechSynthesisUtterance(q);u.onend=function(){if(version===playbackVersion)stopPlayback()};u.onerror=function(){if(version!==playbackVersion)return;if(automatic)autoQuestionPlayback=false;stopPlayback();if(status)status.textContent='Audio unavailable. You can read the question.'};window.speechSynthesis.speak(u)}else{if(automatic)autoQuestionPlayback=false;stopPlayback();if(status)status.textContent='Audio unavailable. You can read the question.'}}}
document.addEventListener('click',function(e){var b=e.target.closest?e.target.closest('.speak-question'):null;if(!b)return;if(b.dataset.playing==='yes'){stopPlayback();return}playQuestion(b,false)});
var recorder=null,recordingStream=null,voiceBusy=false,recordingTimer=null,recordingVersion=0;
function stopRecording(){if(recorder&&recorder.state==='recording'){try{recorder.stop()}catch(e){}}}
window.addEventListener('pagehide',function(){stopPlayback();stopRecording();if(recordingStream)recordingStream.getTracks().forEach(function(t){t.stop()})});
document.addEventListener('click',async function(e){var b=e.target.closest?e.target.closest('.record-answer'):null;if(!b)return;var form=b.closest('form');var status=form.querySelector('.voice-status');var answer=form.querySelector('#answer');if(recorder&&recorder.state==='recording'){stopRecording();return}if(voiceBusy)return;stopPlayback();if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){status.textContent='Recording is unavailable here. You can type your answer.';return}voiceBusy=true;status.textContent='Waiting for microphone permission';var version=++recordingVersion;try{recordingStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!form.isConnected||version!==recordingVersion){recordingStream.getTracks().forEach(function(t){t.stop()});voiceBusy=false;return}var types=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];var type=null;for(var i=0;i<types.length;i++){try{if(MediaRecorder.isTypeSupported(types[i])){type=types[i];break}}catch(ee){}}recorder=type?new MediaRecorder(recordingStream,{mimeType:type}):new MediaRecorder(recordingStream);var parts=[];recorder.ondataavailable=function(ev){if(ev.data&&ev.data.size)parts.push(ev.data)};recorder.onstop=async function(){clearTimeout(recordingTimer);recordingStream.getTracks().forEach(function(t){t.stop()});b.textContent='Record answer';if(version!==recordingVersion){voiceBusy=false;return}status.textContent='Transcribing';try{var blob=new Blob(parts,{type:recorder.mimeType});if(!blob.size)throw new Error('empty');var c=new AbortController();setTimeout(function(){c.abort()},50000);var res=await fetch('/speech/transcribe',{method:'POST',headers:{'Content-Type':blob.type},body:blob,signal:c.signal});if(!res.ok){var failure=new Error('transcribe');failure.status=res.status;throw failure}var data=await res.json();if(!form.isConnected||version!==recordingVersion)return;if(!data.transcript||!data.transcript.trim()){status.textContent='No speech was detected. Try again or type your answer.';return}var combined=(answer.value?answer.value+' ':'')+data.transcript;if(combined.length>2000){status.textContent='The transcript is too long to add. Shorten your answer and try again.';return}answer.value=combined;answer.dispatchEvent(new Event('input',{bubbles:true}));status.textContent='Review and edit your answer before sending.'}catch(err){if(form.isConnected)status.textContent=(err&&err.status===429)?'Transcription limit reached. You can type your answer.':(err&&err.status===503)?'Transcription is unavailable right now. You can type your answer.':'Could not transcribe this recording. Please try again or type your answer.'}finally{voiceBusy=false}};recorder.start();b.textContent='Stop recording';status.textContent='Recording. Tap Stop when you are finished.';recordingTimer=setTimeout(stopRecording,120000)}catch(err){if(recordingStream)recordingStream.getTracks().forEach(function(t){t.stop()});voiceBusy=false;status.textContent='Microphone unavailable or permission denied. You can type your answer.'}});
document.addEventListener('click',async function(e){var outcome=e.target.closest?e.target.closest('.copy-outcome'):null;if(outcome){var st=outcome.parentElement.querySelector('.copy-status');try{await navigator.clipboard.writeText(outcome.closest('.record').querySelector('textarea').value);st.textContent='Copied.'}catch(err){st.textContent='Select the wording above to copy it.'}return}var button=e.target.closest?e.target.closest('.copy-reviewed'):null;if(!button)return;var s2=button.parentElement.querySelector('.copy-status');try{await navigator.clipboard.writeText(button.closest('.record').querySelector('.reviewed-experience').textContent);s2.textContent='Copied.'}catch(err){s2.textContent='Could not copy. Select the text above to copy it.'}});
document.addEventListener('input',function(e){if(e.target&&e.target.id==='answer'){e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,240)+'px';try{sessionStorage.setItem('realize-draft',JSON.stringify({text:e.target.value,question:document.querySelector('.question p')?document.querySelector('.question p').textContent:''}))}catch(err){}}});
document.addEventListener('keydown',function(e){if(e.target&&e.target.id==='answer'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit()}});
document.getElementById('theme').addEventListener('click',function(){var d=document.documentElement,c=d.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');d.dataset.theme=c==='dark'?'light':'dark';try{localStorage.setItem('theme',d.dataset.theme)}catch(e){}});
(function(){var ctx=document.getElementById('context');if(ctx&&matchMedia('(min-width: 701px)').matches)ctx.open=true;var pd=document.getElementById('portrait-detail');if(pd&&matchMedia('(min-width: 1101px)').matches)pd.open=true})();
document.addEventListener('submit',async function(e){var form=e.target;if(!form||form.method.toLowerCase()!=='post')return;var previousQuestion=document.querySelector('.question p')?document.querySelector('.question p').textContent:null;recordingVersion++;if(recorder&&recorder.state==='recording')stopRecording();e.preventDefault();if(sending)return;stopPlayback();var data=new FormData(form);if(e.submitter&&e.submitter.name)data.append(e.submitter.name,e.submitter.value);var body=form.enctype==='multipart/form-data'?data:new URLSearchParams(data);var answer=form.querySelector('#answer');var draft=answer?answer.value:null;if(answer){try{sessionStorage.setItem('realize-draft',JSON.stringify({text:draft,question:document.querySelector('.question p')?document.querySelector('.question p').textContent:''}))}catch(err){}}var nearBottom=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-180;var hadSignal=!!document.querySelector('.signal');sending=true;form.classList.add('busy');if(answer){var msg=document.createElement('div');msg.className='message user optimistic';var label=document.createElement('small');label.textContent='You';var pp=document.createElement('p');pp.textContent=draft;msg.append(label,pp);form.before(msg);answer.value=''}var pending=document.createElement('p');pending.className='pending-message';pending.setAttribute('role','status');pending.textContent=form.classList.contains('infer')?'Realize is working on your request':'Processing';form.before(pending);document.querySelectorAll('#app button, #app input, #app textarea').forEach(function(el){el.disabled=true});if(nearBottom&&pending.scrollIntoView)pending.scrollIntoView({block:'nearest'});try{var response=await fetch(form.action,{method:'POST',body:body,headers:{'X-Realize-Fragment':'1'}});if(!response.ok)throw new Error('Request failed');var html=await response.text();var doc=new DOMParser().parseFromString(html,'text/html');var next=doc.querySelector('#app');if(!next)throw new Error('Invalid response');var actPath=new URL(form.action).pathname;if((actPath==='/reveal'&&next.querySelector('.recognition'))||(actPath==='/connections'&&next.querySelector('.connection-stage')))next.classList.add('reveal-enter');document.querySelector('#app').replaceWith(next);var nq=next.querySelector('.question p');if(nq&&nq.textContent!==previousQuestion&&autoQuestionPlayback)playQuestion(next.querySelector('.speak-question'),true);if(answer){try{sessionStorage.removeItem('realize-draft')}catch(err){}}else restoreDraft(next);if(next.querySelector('.notice')){for(var pair of data){var field=next.querySelector('[name="'+pair[0]+'"]');if(field&&field.type!=='file'&&typeof pair[1]==='string'&&(field.tagName==='TEXTAREA'||field.type==='text'))field.value=pair[1]}}var focus=next.querySelector('#answer')||next.querySelector('[role="alert"]')||next.querySelector('.discovery-stage > h1, .discovery h2, .narrow > h2, .wide > h1, .wide > h2')||next.querySelector('h1, h2')||next;focus.setAttribute('tabindex',focus.getAttribute('tabindex')||'-1');focus.focus({preventScroll:true});if(answer&&nearBottom){var t=(next.querySelector('.signal')&&!hadSignal?next.querySelector('.signal'):null)||next.querySelector('.question')||focus;if(t&&t.scrollIntoView)t.scrollIntoView({block:'start'})}else if(!answer){var t2=next.querySelector('.discovery-stage > h1')||next.querySelector('.question')||(next.querySelector('.discovery')?next.querySelector('.discovery').parentElement:null)||focus;if(t2&&t2.scrollIntoView)t2.scrollIntoView({block:'start'})}}catch(err){document.querySelectorAll('#app button, #app input, #app textarea').forEach(function(el){el.disabled=false});if(pending&&pending.remove)pending.remove();form.classList.remove('busy');var opt=document.querySelector('.optimistic');if(opt)opt.remove();if(answer)answer.value=draft;var alert=document.createElement('div');alert.className='client-error';alert.setAttribute('role','alert');alert.textContent='The connection was interrupted. Your draft is still here. The server may have recorded it; refresh before sending again to check the session.';form.before(alert);alert.setAttribute('tabindex','-1');alert.focus({preventScroll:true});if(alert.scrollIntoView)alert.scrollIntoView({block:'nearest'});if(answer){form.querySelectorAll('button').forEach(function(el){el.disabled=true});answer.readOnly=true}}finally{sending=false}});
</script></body></html>`
